# Write your MySQL query statement below
SELECT a1.student_id, a1.student_name, a3.subject_name, COUNT(a2.subject_name) AS attended_exams FROM Students a1 CROSS JOIN Subjects a3 LEFT JOIN Examinations a2 ON a1.student_id=a2.student_id AND a3.subject_name=a2.subject_name GROUP BY a1.student_id,a3.subject_name ORDER BY a1.student_id,a3.subject_name;